Fix: multiply the cart's current price, not a stored original.

```ts
// before (likely)
function withDiscount(cart: Cart, rate: number): Cart {
  return { ...cart, price: cart.basePrice * (1 - rate) };
}

// after
function withDiscount(cart: Cart, rate: number): Cart {
  return { ...cart, price: cart.price * (1 - rate) };
}
```

